public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate basic inputs
    if (n <= 0 || start == null || end == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }
    // If start equals end, trivially reachable
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }
    // Build adjacency map
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
    if (paths != null) {
        for (int[] p : paths) {
            if (p == null || p.length != 4) continue;
            int x1 = p[0], y1 = p[1], x2 = p[2], y2 = p[3];
            // Validate coordinates within bounds
            if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
                continue;
            }
            String key1 = x1 + "," + y1;
            String key2 = x2 + "," + y2;
            graph.computeIfAbsent(key1, k -> new java.util.ArrayList<>()).add(key2);
            graph.computeIfAbsent(key2, k -> new java.util.ArrayList<>()).add(key1);
        }
    }
    // BFS
    java.util.Queue<String> queue = new java.util.LinkedList<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    String startKey = start[0] + "," + start[1];
    String endKey = end[0] + "," + end[1];
    queue.offer(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String cur = queue.poll();
        if (cur.equals(endKey)) {
            return "can be travelled";
        }
        java.util.List<String> neighbors = graph.get(cur);
        if (neighbors == null) continue;
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.offer(nb);
            }
        }
    }
    return "cannot be travelled";
}

