public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;

    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) dp[i] = new java.util.HashSet<>();
    dp[0].add(0);

    for (int num : nums) {
        for (int size = n - 1; size >= 1; size--) {
            if (dp[size - 1].isEmpty()) continue;
            for (int sum : dp[size - 1]) {
                dp[size].add(sum + num);
            }
        }
    }

    for (int k = 1; k <= n / 2; k++) {
        long product = (long) totalSum * k;
        if (product % n != 0) continue;
        int target = (int) (product / n);
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    // Handle null or empty input
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    // If there's only one step, the minimum cost is the cost of that step
    if (n == 1) {
        return cost[0];
    }
    // dp[i] represents the minimum cost to reach step i
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        int costFromPrev = dp[i - 1] + cost[i - 1];
        int costFromPrevPrev = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(costFromPrev, costFromPrevPrev);
    }
    return dp[n];
}

