public boolean hasAllCodes(String s, int k) {
    // Validate input
    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    // If k is too large, 2^k may exceed array bounds or be impossible
    if (k > 20) { // 2^20 = 1,048,576, reasonable upper bound
        return false;
    }
    int total = 1 << k;
    if (n < k) {
        return false;
    }
    boolean[] seen = new boolean[total];
    int mask = 0;
    int maskLimit = total - 1;
    int count = 0;
    for (int i = 0; i < n; i++) {
        // Build mask for current window
        mask = ((mask << 1) & maskLimit) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[mask]) {
                seen[mask] = true;
                count++;
                if (count == total) {
                    return true; // All codes found early
                }
            }
        }
    }
    return count == total;
}

