        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            // Check if c and top are same letter with opposite cases
            if (Math.abs(c - top) == 32 && Character.toLowerCase(c) == Character.toLowerCase(top)) {
