}

private void dfs(String s, int pos, java.util.HashSet<String> used, int[] max) {
    if (pos == s.length()) {
        if (used.size() > max[0]) max[0] = used.size();
        return;
    }
    for (int i = pos + 1; i <= s.length(); i++) {
        String sub = s.substring(pos, i);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(s, i, used, max);
            used.remove(sub);
        }
    }
}

