public String getSmallestString(int n, int k) {
    // Validate input: n must be non-negative and k must be achievable
    if (n <= 0 || k < n || k > 26 * n) {
        return "";
    }
    StringBuilder sb = new StringBuilder(n);
    for (int i = 0; i < n; i++) {
        int remainingPositions = n - i - 1;
        int maxRemaining = remainingPositions * 26;
        // Minimum value for current position to still allow a valid completion
        int minVal = Math.max(1, k - maxRemaining);
        // Ensure the value does not exceed 26
        if (minVal > 26) {
            // This should not happen due to earlier validation, but guard anyway
            return "";
        }
        char ch = (char) ('a' + minVal - 1);
        sb.append(ch);
        k -= minVal;
    }
    return sb.toString();
}

