    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long current = queue.poll();
        if (current > high) {
            continue;
        }
        if (current >= low) {
            result.add((int) current);
        }
        int lastDigit = (int) (current % 10);
        if (lastDigit > 0) {
            long next = current * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = current * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }
    java.util.Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n % factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    if (n <= 0) {
        return false;
    }
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    if (n == 0) {
        return 0;
    }
    // Initialize DP arrays
    int[][] horiz = new int[m][n];
    int[][] vert = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] antiDiag = new int[m][n];
    int maxLen = 0;
    for (int i = 0; i < m; i++) {
        if (mat[i] == null || mat[i].length != n) {
            // Inconsistent row length; treat as all zeros
            continue;
        }
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horiz[i][j] = (j > 0 ? horiz[i][j - 1] : 0) + 1;
                vert[i][j] = (i > 0 ? vert[i - 1][j] : 0) + 1;
                diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                antiDiag[i][j] = (i > 0 && j < n - 1 ? antiDiag[i - 1][j + 1] : 0) + 1;
                int localMax = Math.max(Math.max(horiz[i][j], vert[i][j]),
                                        Math.max(diag[i][j], antiDiag[i][j]));
                if (localMax > maxLen) {
                    maxLen = localMax;
                }
            } else {
                horiz[i][j] = 0;
                vert[i][j] = 0;
                diag[i][j] = 0;
                antiDiag[i][j] = 0;
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    // Handle negative numbers and Integer.MIN_VALUE safely
    boolean negative = n < 0;
    long absVal = negative ? -(long) n : n;
    String numStr = Long.toString(absVal);
    int len = numStr.length();

    // Determine the size of the first group
    int firstGroup = len % 3;
    if (firstGroup == 0) {
        firstGroup = 3;
    }

    StringBuilder sb = new StringBuilder();
    sb.append(numStr.substring(0, firstGroup));

    for (int i = firstGroup; i < len; i += 3) {
        sb.append('.');
        sb.append(numStr.substring(i, i + 3));
    }

    if (negative) {
        sb.insert(0, '-');
    }

    return sb.toString();
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }
    int n = A.length;
    if (n == 1) {
        return 1;
    }
    // Build frequency map
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : A) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    // Precompute perfect squares up to 2*max(A)
    int maxVal = 0;
    for (int num : A) {
        if (num > maxVal) maxVal = num;
    }
    int maxSum = 2 * maxVal;
    java.util.Set<Integer> squares = new java.util.HashSet<>();
    for (int i = 0; i * i <= maxSum; i++) {
        squares.add(i * i);
    }
    java.util.Map<String, Integer> memo = new java.util.HashMap<>();
    java.util.List<Integer> uniqueNums = new java.util.ArrayList<>(freq.keySet());
    java.util.Collections.sort(uniqueNums);
    return dfs(-1, freq, uniqueNums, squares, memo);
}

private static int dfs(int last, java.util.Map<Integer, Integer> freq,
                       java.util.List<Integer> uniqueNums,
                       java.util.Set<Integer> squares,
                       java.util.Map<String, Integer> memo) {
    // Build memo key
    StringBuilder keyBuilder = new StringBuilder();
    keyBuilder.append(last).append('#');
    for (int num : uniqueNums) {
        int cnt = freq.getOrDefault(num, 0);
        if (cnt > 0) {
            keyBuilder.append(num).append(':').append(cnt).append(',');
        }
    }
    String key = keyBuilder.toString();
    if (memo.containsKey(key)) {
        return memo.get(key);
    }
    int remaining = 0;
    for (int cnt : freq.values()) {
        remaining += cnt;
    }
    if (remaining == 0) {
        return 1;
    }
    int total = 0;
    for (int num : uniqueNums) {
        int cnt = freq.getOrDefault(num, 0);
        if (cnt == 0) continue;
        if (last != -1 && !squares.contains(last + num)) continue;
        freq.put(num, cnt - 1);
        total += dfs(num, freq, uniqueNums, squares, memo);
        freq.put(num, cnt);
    }
    memo.put(key, total);
    return total;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n + 1];
    int top = -1;
    long maxArea = 0;
    for (int i = 0; i <= n; i++) {
        int curHeight = (i == n) ? 0 : heights[i];
        while (top >= 0 && curHeight < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    return (int) maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    // Handle potential ragged arrays by determining the maximum row length
    for (int i = 1; i < m; i++) {
        if (mat[i] != null && mat[i].length > n) {
            n = mat[i].length;
        }
    }
    int total = 0;
    for (int i = 0; i < m; i++) {
        if (mat[i] != null) {
            total += mat[i].length;
        }
    }
    int[] result = new int[total];
    int idx = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        for (int i = 0; i <= sum; i++) {
            int j = sum - i;
            if (i < m && j < mat[i].length && mat[i] != null) {
                result[idx++] = mat[i][j];
            }
        }
    }
    return result;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    List<String> all = buildStrobogrammatic(n, n);
    for (String s : all) {
        if (s.length() > 1 && s.charAt(0) == '0') {
            continue;
        }
        result.add(s);
    }
    result.sort(null);
    return result;
}

private static List<String> buildStrobogrammatic(int current, int total) {
    if (current == 0) {
        List<String> base = new ArrayList<>();
        base.add("");
        return base;
    }
    if (current == 1) {
        List<String> base = new ArrayList<>();
        base.add("0");
        base.add("1");
        base.add("8");
        return base;
    }
    List<String> prev = buildStrobogrammatic(current - 2, total);
    List<String> res = new ArrayList<>();
    for (String s : prev) {
        res.add("0" + s + "0");
        res.add("1" + s + "1");
        res.add("6" + s + "9");
        res.add("8" + s + "8");
        res.add("9" + s + "6");
    }
    return res;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length != 2) {
            return false;
        }
    }
    // Check for duplicate points
    if (points[0][0] == points[1][0] && points[0][1] == points[1][1]) {
        return false;
    }
    if (points[0][0] == points[2][0] && points[0][1] == points[2][1]) {
        return false;
    }
    if (points[1][0] == points[2][0] && points[1][1] == points[2][1]) {
        return false;
    }
    long x1 = points[0][0], y1 = points[0][1];
    long x2 = points[1][0], y2 = points[1][1];
    long x3 = points[2][0], y3 = points[2][1];
    long area = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);
    return area != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int maxLen = 1;
    int currentLen = 1;
    char prev = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == prev) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            currentLen = 1;
            prev = c;
        }
    }
    if (currentLen > maxLen) {
        maxLen = currentLen;
    }
    return maxLen;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>(n);
    if (n <= 0) {
        return result;
    }
    long cur = 1;
    long limit = n;
    for (int i = 0; i < n; i++) {
        result.add((int) cur);
        if (cur * 10 <= limit) {
            cur *= 10;
        } else if (cur % 10 != 9 && cur + 1 <= limit) {
            cur++;
        } else {
            while ((cur / 10) % 10 == 9 || cur + 1 > limit) {
                cur /= 10;
            }
            cur++;
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.HashMap<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    // Helper to check perfect square
    java.util.function.IntPredicate isSquare = x -> {
        int r = (int) Math.sqrt(x);
        return r * r == x;
    };
    // 1. Check if n itself is a perfect square
    if (isSquare.test(n)) {
        return 1;
    }
    // 2. Check if n can be expressed as sum of two perfect squares
    int limit = (int) Math.sqrt(n);
    for (int i = 1; i <= limit; i++) {
        int remainder = n - i * i;
        if (isSquare.test(remainder)) {
            return 2;
        }
    }
    // 3. Apply Legendre's three-square theorem
    int temp = n;
    while (temp % 4 == 0) {
        temp /= 4;
    }
    if (temp % 8 == 7) {
        return 4;
    }
    // 4. Otherwise, answer is 3
    return 3;
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c != ' ') {
            word.append(c);
        } else {
            if (word.length() > 0) {
                result.append(word.reverse());
                word.setLength(0);
            }
            result.append(' ');
        }
    }
    if (word.length() > 0) {
        result.append(word.reverse());
    }
    return result.toString();
}
